{  
   "requirements": [  
      {  
         "id": "10",  
         "text": "Free play in the steering system must not exceed specified tolerances to prevent on-road steering imprecision.",  
         "explanation": "This requirement ensures that any slack or looseness within the steering mechanism is kept within acceptable limits. Excessive free play can lead to delayed response when turning the steering wheel, causing difficulty in controlling the vehicle accurately. By maintaining tight tolerances, drivers experience more precise and predictable steering behavior, enhancing safety and handling performance."
      },  
      {  
         "id": "34",  
         "text": "Vehicle control systems must process yaw rate data in real-time to enable immediate corrective actions.",  
         "explanation": "This requirement emphasizes the importance of processing yaw rate data—information about how quickly a vehicle is rotating around its vertical axis—in real time. Real-time processing allows the vehicle's control systems, such as electronic stability control (ESC), to detect and respond to potential loss of traction or skidding situations promptly. Immediate corrective actions can include adjusting engine power, applying brakes to specific wheels, or modifying steering inputs to help maintain vehicle stability and prevent accidents."
      }  
   ]  
}

